const issues = $input.all();
const items = [];

const templates = {
  hot_take: '{topic}. Most teams handle this wrong. Here\'s why: {angle}. The fix isn\'t more tools. It\'s evidence. Open source: github.com/DNYoussef/codeguard-action',
  case_study: 'We ran {tool} on {repo}. {finding}. Evidence bundle: {link}. Try it: github.com/DNYoussef/codeguard-action',
  byok_deep_dive: '{topic}. Your keys never leave your infra. That\'s not a feature -- it\'s architecture. Here\'s how: {angle}',
  regulatory: '{regulation} requires {requirement}. Most teams solve this with a checkbox. That won\'t survive audit. github.com/DNYoussef/codeguard-action'
};

for (const item of issues) {
  const issue = item.json;
  let desc;
  try { desc = JSON.parse(issue.description || '{}'); } catch { desc = {}; }
  const contentType = desc.content_type || 'linkedin_post';
  const topic = desc.topic || issue.title || 'Code governance';
  const angle = desc.angle || 'hot_take';
  const tool = desc.tool || 'codeguard-action';
  const repo = desc.repo || 'a production repo';
  const finding = desc.finding || 'Caught a risky change before merge';
  const link = desc.link || 'github.com/DNYoussef/codeguard-action';
  const regulation = desc.regulation || 'SOC 2';
  const requirement = desc.requirement || 'evidence of code review';

  const templateKey = (angle in templates) ? angle : 'hot_take';
  const template = templates[templateKey];
  const draft = template
    .replace('{topic}', topic)
    .replace('{angle}', angle !== templateKey ? angle : 'proportional governance')
    .replace('{tool}', tool)
    .replace('{repo}', repo)
    .replace('{finding}', finding)
    .replace('{link}', link)
    .replace('{regulation}', regulation)
    .replace('{requirement}', requirement);

  items.push({json: {
    issue_id: issue.id,
    title: issue.title,
    content_type: contentType,
    topic,
    angle: templateKey,
    draft
  }});
}
return items;
